<?php
function nexa_antispam_ensure(): void { if(!table_exists('spam_log')) create_table('spam_log',['kind','content','ip','reason','created_at']); }
nexa_antispam_ensure();
function nexa_antispam_check(): void { if(!empty($GLOBALS['adminarea']) || (($_SERVER['REQUEST_METHOD']??'GET')!=='POST')) return; $text=''; foreach(['cm_body','c_message','c_subject','f_message','message','body'] as $k) $text.=' '.(string)($_POST[$k]??''); if(trim($text)==='') return; nexa_antispam_ensure(); $reasons=[]; $links=preg_match_all('#https?://#i',$text); if($links>2) $reasons[]='too many links ('.$links.')'; foreach(array_filter(array_map('trim',explode(',',(string)get_setting('antispam_words','viagra,casino,crypto giveaway,free money')))) as $bw) if(stripos($text,$bw)!==false) $reasons[]='banned word: '.$bw; $ip=(string)($_SERVER['REMOTE_ADDR']??''); $recent=count(query("SELECT id FROM spam_log WHERE ip=? AND created_at > ?",[$ip,date('Y-m-d H:i:s',time()-3600)])); if($recent>=5) $reasons[]='repeat spam IP'; if($reasons){ query("INSERT INTO spam_log (kind,content,ip,reason,created_at) VALUES (?,?,?,?,?)",['post',mb_substr(trim($text),0,250),$ip,implode('; ',$reasons),date('Y-m-d H:i:s')]); http_response_code(403); echo '<h2>Blocked as spam</h2><p>Your submission looked like spam ('.esc_html(implode('; ',$reasons)).'). If this is a mistake, please contact the site owner.</p>'; exit; } }
